    23	/// A fully-assembled Bedrock Converse request, ready to send.
    24	///
    25	/// The fields map onto the Bedrock SDK `converse` / `converse_stream` input
    26	/// parameters. Callers should inspect `synthesizing` to decide how to route
    27	/// stream events (synthesized structured output → `TokenDelta` remapping).
    28	#[derive(Debug)]
    29	pub(crate) struct PreparedConverse {
    30	    /// Bedrock model identifier (may include cross-region profile prefix).
    31	    pub(crate) model_id: String,
    32	    /// System prompt blocks.
    33	    pub(crate) system: Vec<SystemContentBlock>,
    34	    /// Conversation turns. Adjacent same-role turns are joined.
    35	    pub(crate) messages: Vec<Message>,
    36	    /// Tool configuration (tools list + optional tool_choice).
    37	    pub(crate) tool_config: Option<ToolConfiguration>,
    38	    /// Base inference parameters.
    39	    pub(crate) inference_config: Option<InferenceConfiguration>,
    40	    /// Whether the stream translator should remap the synthesized tool's
    41	    /// output to `TokenDelta`.
    42	    pub(crate) synthesizing: bool,
    43	}
    44	
    45	/// Build an [`InferenceConfiguration`] from per-request settings and the builder config.
    46	///
    47	/// `maxTokens` is set only when the caller explicitly provided
    48	/// `max_output_tokens` on the request or the builder was configured with
    49	/// [`crate::BedrockModelBuilder::max_output_tokens_default`]. Omitting
    50	/// `maxTokens` lets each Bedrock model apply its own correct default, which
    51	/// avoids `ValidationException` on models whose limit is below any hardcoded
    52	/// value.
    53	///
    54	/// Returns `None` when all three fields (temperature, top_p, max_tokens) are
    55	/// absent — Bedrock accepts a missing `inferenceConfig` and all its fields are
    56	/// individually optional.
    57	fn build_inference_config(req: &ModelRequest, cfg: &Config) -> Option<InferenceConfiguration> {
    58	    let max_tokens = req
    59	        .model_settings
    60	        .max_output_tokens
    61	        .or(cfg.max_output_default);
    62	
    63	    // When no inference field is set, omit the config block entirely.
    64	    if req.model_settings.temperature.is_none()
    65	        && req.model_settings.top_p.is_none()
    66	        && max_tokens.is_none()
    67	    {
    68	        return None;
    69	    }
    70	
    71	    let mut b = InferenceConfiguration::builder();
    72	    if let Some(t) = req.model_settings.temperature {
    73	        b = b.temperature(t);
    74	    }
    75	    if let Some(p) = req.model_settings.top_p {
    76	        b = b.top_p(p);
    77	    }
    78	    if let Some(mt) = max_tokens {
    79	        b = b.max_tokens(mt as i32);
    80	    }
    81	    Some(b.build())
    82	}
