    84	/// Assemble a [`PreparedConverse`] from the builder `Config` and a [`ModelRequest`].
    85	///
    86	/// # Errors
    87	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
    88	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::Tool` (conflict).
    89	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::None` (conflict).
    90	/// - No message with content after empty/whitespace-only text is dropped.
    91	/// - The last user message had only empty/whitespace-only text and the request would end with an assistant message.
    92	pub(crate) fn build_request(
    93	    cfg: &Config,
    94	    req: &ModelRequest,
    95	) -> Result<PreparedConverse, ModelError> {
    96	    let family = cfg.family;
    97	    let ruleset = Ruleset::for_family(family);
    98	
    99	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::Tool → conflict.
   100	    let synthesizing_rf = matches!(
   101	        req.model_settings.response_format.as_ref(),
   102	        Some(paigasus_helikon_core::ResponseFormat::JsonSchema { .. })
   103	            | Some(paigasus_helikon_core::ResponseFormat::JsonObject),
   104	    );
   105	    let forced_tool = matches!(
   106	        req.model_settings.tool_choice.as_ref(),
   107	        Some(ToolChoice::Tool { .. }),
   108	    );
   109	    if synthesizing_rf && family.supports_forced_tool_choice() && forced_tool {
   110	        return Err(ModelError::Other(anyhow::anyhow!(
   111	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::Tool are mutually \
   112	             exclusive on Bedrock — use one or the other",
   113	        )));
   114	    }
   115	
   116	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::None → conflict.
   117	    // Synthesis requires injecting a tool; ToolChoice::None suppresses toolConfig entirely.
   118	    let none_choice = matches!(
   119	        req.model_settings.tool_choice.as_ref(),
   120	        Some(ToolChoice::None),
   121	    );
   122	    if synthesizing_rf && family.supports_forced_tool_choice() && none_choice {
   123	        return Err(ModelError::Other(anyhow::anyhow!(
   124	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::None are mutually \
   125	             exclusive on Bedrock — structured-output synthesis requires a tool call",
   126	        )));
   127	    }
   128	
   129	    // ToolChoice::None means the model MUST NOT call any tool this turn.
   130	    // Omit toolConfig entirely (do not send user tools either).
   131	    if none_choice {
   132	        let translated = items_to_messages(&req.messages)?;
   133	        let inference_config = build_inference_config(req, cfg);
   134	        return Ok(PreparedConverse {
   135	            model_id: cfg.model_id.clone(),
   136	            system: translated.system,
   137	            messages: translated.messages,
   138	            tool_config: None,
   139	            inference_config,
   140	            synthesizing: false,
   141	        });
   142	    }
   143	
   144	    // Translate messages.
   145	    let translated = items_to_messages(&req.messages)?;
   146	
   147	    // Translate user tool defs (also validates reserved name).
   148	    let user_specs = tool_specs(&req.tools, ruleset)?;
   149	
   150	    // Synthesize structured output tool (if applicable).
   151	    let Synthesized {
   152	        tool: synth_tool,
   153	        tool_choice: synth_tc,
   154	        synthesizing,
   155	    } = synthesize(req.model_settings.response_format.as_ref(), family, ruleset)?;
   156	
   157	    // Merge tool lists: user tools first, synthesized appended.
   158	    let mut all_tools: Vec<Tool> = user_specs.into_iter().map(Tool::ToolSpec).collect();
   159	    if let Some(st) = synth_tool {
   160	        all_tools.push(Tool::ToolSpec(st));
   161	    }
   162	
   163	    // Build ToolConfiguration (only when there are tools or a tool_choice).
   164	    let caller_tc = req
   165	        .model_settings
   166	        .tool_choice
   167	        .as_ref()
   168	        .and_then(|tc| translate_tool_choice(tc, family));
   169	
   170	    // Synthesis overrides caller tool_choice.
   171	    // synth_tool.is_some() always pushes to all_tools above, so a synthesized tool_choice is never silently dropped here.
   172	    let effective_tc = synth_tc.or(caller_tc);
   173	
   174	    // Validate forced tool choices on supported families.
   175	    // (On unsupported families, forced choices were already omitted by translate_tool_choice.)
   176	    if family.supports_forced_tool_choice() {
   177	        match req.model_settings.tool_choice.as_ref() {
   178	            Some(ToolChoice::Required) if !synthesizing => {
   179	                if all_tools.is_empty() {
   180	                    return Err(ModelError::Other(anyhow::anyhow!(
   181	                        "ToolChoice::Required requires at least one tool to be defined",
   182	                    )));
   183	                }
   184	            }
   185	            Some(ToolChoice::Tool { name }) => {
   186	                let tool_names: Vec<&str> = all_tools
   187	                    .iter()
   188	                    .filter_map(|t| {
   189	                        if let Tool::ToolSpec(spec) = t {
   190	                            Some(spec.name())
   191	                        } else {
   192	                            None
   193	                        }
   194	                    })
   195	                    .collect();
   196	                if !tool_names.contains(&name.as_str()) {
   197	                    return Err(ModelError::Other(anyhow::anyhow!(
   198	                        "ToolChoice::Tool references tool {:?} which is not defined in the tool list",
   199	                        name,
   200	                    )));
   201	                }
   202	            }
   203	            _ => {}
   204	        }
   205	    }
   206	
   207	    let tool_config = if !all_tools.is_empty() {
   208	        let mut builder = ToolConfiguration::builder();
   209	        for t in all_tools {
   210	            builder = builder.tools(t);
   211	        }
   212	        if let Some(tc) = effective_tc {
   213	            builder = builder.tool_choice(tc);
   214	        }
   215	        Some(builder.build().map_err(|e| {
   216	            ModelError::Other(anyhow::anyhow!("failed to build ToolConfiguration: {e}"))
   217	        })?)
   218	    } else if effective_tc.is_some() {
   219	        // ToolConfiguration requires at least one tool — skip tool_choice when
   220	        // no tools are present to avoid a build error.
   221	        tracing::debug!(
   222	            target: "paigasus::bedrock::translate",
   223	            "tool_choice requested but no tools provided; omitting ToolConfiguration",
   224	        );
   225	        None
   226	    } else {
   227	        None
   228	    };
   229	
   230	    // Build InferenceConfiguration.
   231	    let inference_config = build_inference_config(req, cfg);
   232	
   233	    Ok(PreparedConverse {
   234	        model_id: cfg.model_id.clone(),
   235	        system: translated.system,
   236	        messages: translated.messages,
   237	        tool_config,
   238	        inference_config,
   239	        synthesizing,
   240	    })
   241	}
   242	
   243	/// Translate a core [`ToolChoice`] into a Bedrock [`BedrockToolChoice`].
   244	///
   245	/// Returns `None` when the family does not support forced tool choice (the
   246	/// `tool_choice` field is omitted from the request). `ToolChoice::None` is
   247	/// handled before this function is called (it suppresses `toolConfig` entirely).
   248	fn translate_tool_choice(tc: &ToolChoice, family: ModelFamily) -> Option<BedrockToolChoice> {
   249	    match tc {
   250	        ToolChoice::Auto => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
   251	        ToolChoice::Required => {
   252	            if !family.supports_forced_tool_choice() {
   253	                tracing::debug!(
   254	                    target: "paigasus::bedrock::translate",
   255	                    ?family,
   256	                    "ToolChoice::Required requested but family does not support forced tool choice; omitting",
   257	                );
   258	                return None;
   259	            }
   260	            Some(BedrockToolChoice::Any(AnyToolChoice::builder().build()))
   261	        }
   262	        ToolChoice::None => {
   263	            // ToolChoice::None is handled early in build_request; unreachable here.
   264	            None
   265	        }
   266	        ToolChoice::Tool { name } => {
   267	            if !family.supports_forced_tool_choice() {
   268	                tracing::debug!(
   269	                    target: "paigasus::bedrock::translate",
   270	                    ?family,
   271	                    tool = %name,
   272	                    "ToolChoice::Tool requested but family does not support forced tool choice; omitting",
   273	                );
   274	                return None;
   275	            }
   276	            match SpecificToolChoice::builder().name(name).build() {
   277	                Ok(s) => Some(BedrockToolChoice::Tool(s)),
   278	                Err(e) => {
   279	                    tracing::warn!(
   280	                        target: "paigasus::bedrock::translate",
   281	                        err = %e,
   282	                        "failed to build SpecificToolChoice; omitting tool_choice",
   283	                    );
   284	                    None
   285	                }
   286	            }
   287	        }
   288	        _ => {
   289	            tracing::debug!(
   290	                target: "paigasus::bedrock::translate",
   291	                "unknown ToolChoice variant; omitting",
   292	            );
   293	            None
   294	        }
   295	    }
   296	}
