   298	// ── Wire-projection (snapshot tests) ─────────────────────────────────────────
   299	
   300	/// Project a [`PreparedConverse`] into a stable [`serde_json::Value`] for
   301	/// snapshot tests.
   302	///
   303	/// This projection is deliberately **not** based on `Debug` output of the SDK
   304	/// types, which can change across SDK version bumps. Instead, it is a hand-written
   305	/// extraction of the semantically relevant fields.
   306	#[cfg(test)]
   307	pub(crate) fn to_wire_json(p: &PreparedConverse) -> serde_json::Value {
   308	    use aws_sdk_bedrockruntime::types::{
   309	        ContentBlock, SystemContentBlock, ToolChoice as SdkToolChoice, ToolResultContentBlock,
   310	    };
   311	    use serde_json::{json, Value};
   312	
   313	    // System blocks
   314	    let system: Vec<Value> = p
   315	        .system
   316	        .iter()
   317	        .map(|s| match s {
   318	            SystemContentBlock::Text(t) => json!({"text": t}),
   319	            _ => json!({"unknown": true}),
   320	        })
   321	        .collect();
   322	
   323	    // Messages
   324	    let messages: Vec<Value> = p
   325	        .messages
   326	        .iter()
   327	        .map(|m| {
   328	            let role = match m.role {
   329	                aws_sdk_bedrockruntime::types::ConversationRole::User => "user",
   330	                aws_sdk_bedrockruntime::types::ConversationRole::Assistant => "assistant",
   331	                _ => "unknown",
   332	            };
   333	            let content: Vec<Value> = m
   334	                .content
   335	                .iter()
   336	                .map(|b| match b {
   337	                    ContentBlock::Text(t) => json!({"text": t}),
   338	                    ContentBlock::ToolUse(tu) => json!({
   339	                        "toolUse": {
   340	                            "toolUseId": tu.tool_use_id,
   341	                            "name": tu.name,
   342	                        }
   343	                    }),
   344	                    ContentBlock::ToolResult(tr) => {
   345	                        let text_content = tr
   346	                            .content
   347	                            .iter()
   348	                            .find_map(|c| {
   349	                                if let ToolResultContentBlock::Text(t) = c {
   350	                                    Some(t.as_str())
   351	                                } else {
   352	                                    None
   353	                                }
   354	                            })
   355	                            .unwrap_or("");
   356	                        json!({
   357	                            "toolResult": {
   358	                                "toolUseId": tr.tool_use_id,
   359	                                "content": [{"text": text_content}],
   360	                            }
   361	                        })
   362	                    }
   363	                    _ => json!({"unknown": true}),
   364	                })
   365	                .collect();
   366	            json!({"role": role, "content": content})
   367	        })
   368	        .collect();
   369	
   370	    // Tool config
   371	    let tool_config: Value = match &p.tool_config {
   372	        None => Value::Null,
   373	        Some(tc) => {
   374	            let tools: Vec<Value> = tc
   375	                .tools()
   376	                .iter()
   377	                .map(|t| match t {
   378	                    Tool::ToolSpec(spec) => {
   379	                        let schema_placeholder = match spec.input_schema() {
   380	                            Some(s) if s.is_json() => json!("<Document>"),
   381	                            _ => Value::Null,
   382	                        };
   383	                        json!({
   384	                            "toolSpec": {
   385	                                "name": spec.name(),
   386	                                "description": spec.description(),
   387	                                "inputSchema": {"json": schema_placeholder},
   388	                            }
   389	                        })
   390	                    }
   391	                    _ => json!({"unknown": true}),
   392	                })
   393	                .collect();
   394	            let tc_value: Value = match tc.tool_choice() {
   395	                None => Value::Null,
   396	                Some(SdkToolChoice::Auto(_)) => json!({"auto": {}}),
   397	                Some(SdkToolChoice::Any(_)) => json!({"any": {}}),
   398	                Some(SdkToolChoice::Tool(s)) => json!({"tool": {"name": s.name()}}),
   399	                _ => json!({"unknown": true}),
   400	            };
   401	            json!({
   402	                "tools": tools,
   403	                "toolChoice": tc_value,
   404	            })
   405	        }
   406	    };
   407	
   408	    // Inference config
   409	    let inference_config: Value = match &p.inference_config {
   410	        None => Value::Null,
   411	        Some(ic) => {
   412	            let mut m = serde_json::Map::new();
   413	            if let Some(t) = ic.temperature() {
   414	                m.insert("temperature".into(), json!(t));
   415	            }
   416	            if let Some(p) = ic.top_p() {
   417	                m.insert("topP".into(), json!(p));
   418	            }
   419	            if let Some(mt) = ic.max_tokens() {
   420	                m.insert("maxTokens".into(), json!(mt));
   421	            }
   422	            Value::Object(m)
   423	        }
   424	    };
   425	
   426	    json!({
   427	        "modelId": p.model_id,
   428	        "system": system,
   429	        "messages": messages,
   430	        "toolConfig": tool_config,
   431	        "inferenceConfig": inference_config,
   432	        "synthesizing": p.synthesizing,
   433	    })
   434	}
