  1	//! Per-handle policy for the forced tool choice and the structured-output path.
  2	
  3	use std::sync::atomic::{AtomicBool, Ordering};
  4	
  5	use crate::family::{rejects_forced_tool_choice, ModelFamily};
  6	
  7	/// The wire path that carries a structured-output or forced-tool request.
  8	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
  9	pub(crate) enum OutputPath {
 10	    /// Use a synthetic forced tool.
 11	    ForcedTool,
 12	    /// Use the native structured-output field.
 13	    Native,
 14	}
 15	
 16	/// A notice that the native path changes the request. Each kind is logged once per handle.
 17	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 18	// Variants are built from Task 4 (build_request).
 19	#[allow(dead_code)]
 20	pub(crate) enum NativeNotice {
 21	    /// `ToolChoice::Required` is omitted.
 22	    RequiredOmitted,
 23	    /// `ToolChoice::Tool` is omitted.
 24	    ToolOmitted,
 25	    /// `ResponseFormat::JsonObject` degrades to text.
 26	    JsonObjectAsText,
 27	}
 28	
 29	/// State that selects the output path for one model handle.
 30	#[derive(Debug)]
 31	pub(crate) struct ForcedChoicePolicy {
 32	    rejects_static: bool,
 33	    learned: AtomicBool,
 34	    family: ModelFamily,
 35	    warned: [AtomicBool; 3],
 36	}
 37	
 38	impl ForcedChoicePolicy {
 39	    /// Make a policy. The static rule comes from the model id.
 40	    pub(crate) fn new(model_id: &str, family: ModelFamily) -> Self {
 41	        Self::with_rule(rejects_forced_tool_choice(model_id), family)
 42	    }
 43	
 44	    /// Make a policy with no static rule.
 45	    #[cfg(test)]
 46	    pub(crate) fn without_static_rule(family: ModelFamily) -> Self {
 47	        Self::with_rule(false, family)
 48	    }
 49	
 50	    fn with_rule(rejects_static: bool, family: ModelFamily) -> Self {
 51	        Self {
 52	            rejects_static,
 53	            learned: AtomicBool::new(false),
 54	            family,
 55	            warned: [
 56	                AtomicBool::new(false),
 57	                AtomicBool::new(false),
 58	                AtomicBool::new(false),
 59	            ],
 60	        }
 61	    }
 62	
 63	    /// The model family of this handle.
 64	    // Used from Task 4 (build_request path selection).
 65	    #[allow(dead_code)]
 66	    pub(crate) fn family(&self) -> ModelFamily {
 67	        self.family
 68	    }
 69	
 70	    /// The output path for the next request.
 71	    pub(crate) fn path(&self) -> OutputPath {
 72	        if self.rejects_static || self.learned.load(Ordering::SeqCst) {
 73	            OutputPath::Native
 74	        } else {
 75	            OutputPath::ForcedTool
 76	        }
 77	    }
 78	
 79	    /// Record that the service rejected a forced tool choice. Returns `true` only for the first call.
 80	    // Used from Task 5 (send fallback).
 81	    #[allow(dead_code)]
 82	    pub(crate) fn record_rejection(&self) -> bool {
 83	        !self.learned.swap(true, Ordering::SeqCst)
 84	    }
 85	
 86	    /// Returns `true` only the first time for each notice kind.
 87	    pub(crate) fn first_notice(&self, n: NativeNotice) -> bool {
 88	        !self.warned[n as usize].swap(true, Ordering::SeqCst)
 89	    }
 90	
 91	    /// Log the notice once per handle.
 92	    // Used from Task 4 (build_request path selection).
 93	    #[allow(dead_code)]
 94	    pub(crate) fn note(&self, n: NativeNotice, model_id: &str) {
 95	        if !self.first_notice(n) {
 96	            return;
 97	        }
 98	        let text = match n {
 99	            NativeNotice::RequiredOmitted => {
100	                "ToolChoice::Required is omitted: this model rejects a forced tool choice"
101	            }
102	            NativeNotice::ToolOmitted => {
103	                "ToolChoice::Tool is omitted: this model rejects a forced tool choice"
104	            }
105	            NativeNotice::JsonObjectAsText => {
106	                "ResponseFormat::JsonObject degrades to text: native output cannot express a free-form object"
107	            }
108	        };
109	        tracing::warn!(target: "paigasus::bedrock::translate", model_id = %model_id, "{text}");
110	    }
111	}
112	
113	#[cfg(test)]
114	mod tests {
115	    use super::*;
116	    use ModelFamily::Anthropic;
117	
118	    #[test]
119	    fn path_for_each_combination() {
120	        assert_eq!(
121	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5-5", Anthropic).path(),
122	            OutputPath::Native
123	        );
124	        assert_eq!(
125	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5", Anthropic).path(),
126	            OutputPath::ForcedTool
127	        );
128	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
129	        assert_eq!(p.path(), OutputPath::ForcedTool);
130	        assert!(p.record_rejection());
131	        assert_eq!(p.path(), OutputPath::Native);
132	        let both = ForcedChoicePolicy::new("us.anthropic.claude-opus-5-5", Anthropic);
133	        both.record_rejection();
134	        assert_eq!(both.path(), OutputPath::Native);
135	    }
136	
137	    #[test]
138	    fn record_rejection_is_true_only_once_across_threads() {
139	        let p = std::sync::Arc::new(ForcedChoicePolicy::without_static_rule(Anthropic));
140	        let firsts: usize = (0..8)
141	            .map(|_| {
142	                let p = p.clone();
143	                std::thread::spawn(move || p.record_rejection())
144	            })
145	            .collect::<Vec<_>>()
146	            .into_iter()
147	            .map(|h| h.join().unwrap() as usize)
148	            .sum();
149	        assert_eq!(firsts, 1);
150	    }
151	
152	    #[test]
153	    fn first_notice_is_true_once_per_kind() {
154	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
155	        assert!(p.first_notice(NativeNotice::RequiredOmitted));
156	        assert!(!p.first_notice(NativeNotice::RequiredOmitted));
157	        assert!(p.first_notice(NativeNotice::ToolOmitted));
158	        assert!(p.first_notice(NativeNotice::JsonObjectAsText));
159	    }
160	}
  1	//! [`BedrockModel`] — the Bedrock Converse API model handle.
  2	//!
  3	//! Wraps an `Arc<Config>` so that the model handle is `Clone + Send + Sync`
  4	//! and the `BoxStream` returned by `invoke` can be `'static + Send`.
  5	
  6	use std::sync::Arc;
  7	
  8	use async_stream::stream;
  9	use async_trait::async_trait;
 10	use futures_core::stream::BoxStream;
 11	use paigasus_helikon_core::{
 12	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
 13	};
 14	
 15	use crate::builder::Config;
 16	use crate::error::{map_sdk_error, map_sdk_http_error};
 17	use crate::policy::ForcedChoicePolicy;
 18	use crate::stream::StreamTranslator;
 19	use crate::translate::build_request;
 20	
 21	// ── BedrockModel ──────────────────────────────────────────────────────────────
 22	
 23	/// An Amazon Bedrock Converse API model handle.
 24	///
 25	/// Construct via [`BedrockModel::converse`] (sync builder) or
 26	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
 27	///
 28	/// The handle is `Clone + Send + Sync` because it holds only `Arc` values.
 29	/// Clones share the state that the handle learns at run time.
 30	#[derive(Debug, Clone)]
 31	pub struct BedrockModel {
 32	    pub(crate) config: Arc<Config>,
 33	    // Read from Task 4 (build_request) and Task 5 (send fallback).
 34	    #[allow(dead_code)]
 35	    pub(crate) policy: Arc<ForcedChoicePolicy>,
 36	}
 37	
 38	// ── Model impl ────────────────────────────────────────────────────────────────
 39	
 40	#[async_trait]
 41	impl Model for BedrockModel {
 42	    /// Stream model events from Amazon Bedrock's Converse API.
 43	    ///
 44	    /// The returned stream is `'static + Send`.
 45	    ///
 46	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
 47	    /// ends immediately without emitting a final `Finish` event (per the core
 48	    /// `Model` trait contract).
 49	    async fn invoke(
 50	        &self,
 51	        request: ModelRequest,
 52	        cancel: CancellationToken,
 53	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
 54	        // Translate the core request into Bedrock wire format (early error on
 55	        // translation failure — before we open any network connection).
 56	        let prepared = build_request(&self.config, &request)?;
 57	
 58	        let synthesizing = prepared.synthesizing;
 59	        let client = self.config.client.clone();
 60	
 61	        // Build the fluent ConverseStream request from the prepared parts.
 62	        let fluent = client
 63	            .converse_stream()
 64	            .model_id(&prepared.model_id)
 65	            .set_messages(Some(prepared.messages))
 66	            .set_system(if prepared.system.is_empty() {
 67	                None
 68	            } else {
 69	                Some(prepared.system)
 70	            })
 71	            .set_tool_config(prepared.tool_config)
 72	            .set_inference_config(prepared.inference_config);
 73	
 74	        let s = stream! {
 75	            // Send the ConverseStream request and obtain the event receiver.
 76	            // Guard with a cancellation check (biased: cancel arm wins) so that
 77	            // a token already fired — or one that fires during the HTTP send —
 78	            // aborts cleanly without opening a dangling Bedrock stream and
 79	            // without emitting Finish (per the Model::invoke cancellation contract).
 80	            let output = tokio::select! {
 81	                biased;
 82	                _ = cancel.cancelled() => { return; }
 83	                result = fluent.send() => {
 84	                    // map_sdk_http_error: fluent.send() returns
 85	                    // SdkError<_, HttpResponse>, so we can extract Retry-After headers.
 86	                    match result {
 87	                        Ok(o) => o,
 88	                        Err(e) => {
 89	                            yield Err(map_sdk_http_error(e));
 90	                            return;
 91	                        }
 92	                    }
 93	                }
 94	            };
 95	
 96	            let mut receiver = output.stream;
 97	            let mut translator = StreamTranslator::new(synthesizing);
 98	
 99	            loop {
100	                let next = tokio::select! {
101	                    biased;
102	                    _ = cancel.cancelled() => {
103	                        // Cancellation: end stream without emitting Finish.
104	                        return;
105	                    }
106	                    r = receiver.recv() => r,
107	                };
108	
109	                match next {
110	                    // Stream exhausted normally (EOF).
111	                    // Flush any buffered stop reason that arrived without a
112	                    // subsequent Metadata event so the consumer always sees
113	                    // a terminal Finish.
114	                    Ok(None) => {
115	                        if let Some(terminal) = translator.finish() {
116	                            yield terminal;
117	                        }
118	                        return;
119	                    }
120	                    // Good event — feed through translator and yield results.
121	                    Ok(Some(event)) => {
122	                        for result in translator.consume(event) {
123	                            yield result;
124	                        }
125	                    }
126	                    // Transport-level error on the event stream.
127	                    Err(e) => {
128	                        yield Err(map_sdk_error(e));
129	                        return;
130	                    }
131	                }
132	            }
133	        };
134	
135	        Ok(Box::pin(s))
136	    }
137	
138	    fn capabilities(&self) -> ModelCapabilities {
139	        self.config.capabilities
140	    }
